<template><div class="routine-page"><div class="page-header-row"><div><span class="eyebrow">একাডেমিক সময়সূচি</span><h1>ক্লাস রুটিন</h1><p>সাপ্তাহিক ক্লাস সময়সূচি তৈরি ও পরিচালনা করুন</p></div><button class="btn btn-primary" @click="showForm=!showForm"><icon name="plus" /> নতুন ক্লাস</button></div><div class="day-tabs"><button v-for="day in days" :key="day" :class="{active:activeDay===day}" @click="activeDay=day">{{day}}</button></div><form v-if="showForm" class="create-panel card" @submit.prevent="create"><div class="form-heading"><h2>রুটিনে নতুন ক্লাস</h2><button type="button" class="close-btn" @click="showForm=false">×</button></div><div v-if="error" class="alert alert-error">{{error}}</div><div class="form-grid"><div class="form-group"><label>বার *</label><select v-model="form.day_of_week" class="form-control" required><option v-for="d in days" :key="d">{{d}}</option></select></div><div class="form-group"><label>শ্রেণি</label><select v-model="form.class_id" class="form-control"><option value="">নির্বাচন করুন</option><option v-for="c in classes" :key="c.id" :value="c.id">{{c.name_bn}}</option></select></div><div class="form-group"><label>বিষয়</label><select v-model="form.subject_id" class="form-control"><option value="">নির্বাচন করুন</option><option v-for="s in subjects" :key="s.id" :value="s.id">{{s.name_bn}}</option></select></div><div class="form-group"><label>শুরু</label><input v-model="form.start_time" type="time" class="form-control" required /></div><div class="form-group"><label>শেষ</label><input v-model="form.end_time" type="time" class="form-control" required /></div></div><div class="form-actions"><button class="btn btn-primary" :disabled="saving">{{saving?'সংরক্ষণ হচ্ছে...':'রুটিনে যোগ করুন'}}</button><button type="button" class="btn btn-ghost" @click="showForm=false">বাতিল</button></div></form><div v-if="loading" class="loading-state"><div class="spinner" /></div><div v-else class="schedule"><div v-for="slot in filtered" :key="slot.id" class="slot-card"><div class="time"><b>{{ time(slot.start_time) }}</b><span>{{ time(slot.end_time) }}</span></div><div class="slot-line" /><div class="slot-body"><span class="subject-badge"><icon name="book" /></span><div><h3>{{slot.subject?.name_bn||'বিষয় নির্ধারিত নয়'}}</h3><p>{{slot.class?.name_bn||'শ্রেণি নির্ধারিত নয়'}} · {{slot.teacher?.name_bn||'শিক্ষক নির্ধারিত নয়'}}</p></div></div><button class="delete-btn" @click="remove(slot.id)"><icon name="delete" /></button></div><div v-if="!filtered.length" class="empty-card"><div class="empty-icon"><icon name="calendar" /></div><h3>{{activeDay}}-এর কোনো ক্লাস নেই</h3><p>নতুন ক্লাস যোগ করে সাপ্তাহিক রুটিন সাজান</p></div></div></div></template>
<script setup lang="ts">import{computed,onMounted,reactive,ref,watch}from'vue';import{useApiClient}from'~/utils/api';const api=useApiClient();const days=['শনিবার','রবিবার','সোমবার','মঙ্গলবার','বুধবার','বৃহস্পতিবার','শুক্রবার'];const activeDay=ref('শনিবার');const rows=ref<any[]>([]);const classes=ref<any[]>([]);const subjects=ref<any[]>([]);const loading=ref(true);const saving=ref(false);const showForm=ref(false);const error=ref('');const form=reactive<any>({day_of_week:'শনিবার',class_id:'',subject_id:'',start_time:'09:00',end_time:'10:00'});const filtered=computed(()=>rows.value.filter(r=>r.day_of_week===activeDay.value));async function load(){loading.value=true;try{const[r,c,s]=await Promise.all([api.get('/timetable'),api.get('/academic/classes'),api.get('/academic/subjects')]);rows.value=r.data?.data||[];classes.value=c.data?.data||[];subjects.value=s.data?.data||[]}catch(e){console.error(e)}finally{loading.value=false}}async function create(){saving.value=true;error.value='';try{await api.post('/timetable',{...form,class_id:form.class_id||null,subject_id:form.subject_id||null});showForm.value=false;await load()}catch(e:any){error.value=e?.response?.data?.message||'রুটিন তৈরি করা যায়নি'}finally{saving.value=false}}async function remove(id:number){if(!confirm('এই ক্লাসটি রুটিন থেকে সরাবেন?'))return;await api.delete(`/timetable/${id}`);await load()}function time(v:string){return v?.slice(0,5)||'—'}watch(activeDay,v=>form.day_of_week=v);onMounted(load)</script>
<style scoped>.routine-page{max-width:1200px;margin:0 auto;padding-bottom:2rem}.page-header-row{display:flex;justify-content:space-between;align-items:flex-end;gap:1rem;margin-bottom:1.3rem}.eyebrow{color:var(--color-primary);font:600 .78rem var(--font-bn)}.page-header-row h1{margin:.25rem 0;color:var(--color-primary);font:700 1.65rem var(--font-bn)}.page-header-row p{color:var(--color-text-light);font:.88rem var(--font-bn)}.day-tabs{display:flex;gap:.3rem;overflow:auto;margin-bottom:1rem;padding:.25rem;background:#fff;border:1px solid var(--color-border-light);border-radius:12px}.day-tabs button{flex:1;min-width:90px;padding:.6rem .8rem;border:0;border-radius:9px;background:transparent;color:var(--color-text-light);font:.78rem var(--font-bn);cursor:pointer}.day-tabs button.active{color:#fff;background:var(--color-primary)}.create-panel{padding:1.2rem;margin-bottom:1rem}.form-heading{display:flex;justify-content:space-between;margin-bottom:1rem}.form-heading h2{font:700 1rem var(--font-bn)}.close-btn{border:0;background:transparent;font-size:1.5rem;color:var(--color-text-muted);cursor:pointer}.form-grid{display:grid;grid-template-columns:repeat(5,1fr);gap:.7rem}.form-group label{display:block;margin-bottom:.3rem;font:600 .78rem var(--font-bn)}.form-actions{display:flex;gap:.6rem;margin-top:1rem}.schedule{display:grid;gap:.7rem}.slot-card{display:grid;grid-template-columns:90px 3px 1fr auto;align-items:center;gap:1rem;padding:1rem;background:#fff;border:1px solid var(--color-border-light);border-radius:15px;box-shadow:var(--shadow-sm)}.time{text-align:right}.time b,.time span{display:block}.time b{color:var(--color-primary);font:700 .9rem var(--font-sans)}.time span{margin-top:.2rem;color:var(--color-text-muted);font:.68rem var(--font-sans)}.slot-line{height:42px;border-radius:99px;background:var(--color-accent)}.slot-body{display:flex;align-items:center;gap:.7rem}.subject-badge{display:grid;place-items:center;width:38px;height:38px;border-radius:12px;color:#7857a9;background:#f0eafb}.slot-body h3{font:700 .9rem var(--font-bn)}.slot-body p{margin-top:.15rem;color:var(--color-text-light);font:.72rem var(--font-bn)}.delete-btn{display:grid;place-items:center;width:30px;height:30px;border:0;border-radius:8px;color:var(--color-error);background:var(--color-error-bg);cursor:pointer}.empty-card{padding:3rem;text-align:center;background:#fff;border:1px dashed var(--color-border);border-radius:18px}.empty-icon{display:grid;place-items:center;width:54px;height:54px;margin:0 auto 1rem;border-radius:16px;color:var(--color-primary);background:var(--color-primary-50);font-size:1.4rem}.empty-card h3{font:700 1rem var(--font-bn)}.empty-card p{color:var(--color-text-light);font:.8rem var(--font-bn)}@media(max-width:800px){.form-grid{grid-template-columns:repeat(2,1fr)}.slot-card{grid-template-columns:70px 3px 1fr auto}}@media(max-width:550px){.page-header-row{align-items:flex-start;flex-direction:column}.form-grid{grid-template-columns:1fr}.slot-card{grid-template-columns:1fr;gap:.5rem}.time{text-align:left}.slot-line{width:100%;height:3px}.delete-btn{justify-self:end}}
</style>
